#include <stdio.h>

static int a[1000], b[1000];
static int printed = 0;

static void put(int value) {
    printf(printed++ ? " %d" : "%d", value);
}

int main(void) {
    int n, m;
    if (scanf("%d", &n) != 1 || n < 0 || n > 1000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    if (scanf("%d", &m) != 1 || m < 0 || m > 1000) {
        return 0;
    }
    for (int j = 0; j < m; j++) {
        scanf("%d", &b[j]);
    }
    int i = 0, j = 0;
    while (i < n && j < m) {
        put(a[i] <= b[j] ? a[i++] : b[j++]);
    }
    while (i < n) {
        put(a[i++]);
    }
    while (j < m) {
        put(b[j++]);
    }
    printf("\n");
    return 0;
}

