static int values[100000], tmp[100000];

static void merge_sort(int lo, int hi) {
    if (hi - lo < 2) {
        return;
    }
    int mid = lo + (hi - lo) / 2;
    merge_sort(lo, mid);
    merge_sort(mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        tmp[k++] = values[i] <= values[j] ? values[i++] : values[j++];
    }
    while (i < mid) {
        tmp[k++] = values[i++];
    }
    while (j < hi) {
        tmp[k++] = values[j++];
    }
    for (k = lo; k < hi; k++) {
        values[k] = tmp[k];
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
