    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    merge_sort(0, n);
    for (int i = 0; i < n; i++) {
        printf(i + 1 < n ? "%d " : "%d\n", values[i]);
    }
    return 0;
