#include <stdio.h>

static int values[100000], tmp[100000];

static long long sort_count(int lo, int hi) {
    if (hi - lo < 2) {
        return 0;
    }
    int mid = lo + (hi - lo) / 2;
    long long inversions = sort_count(lo, mid) + sort_count(mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (values[i] <= values[j]) {
            tmp[k++] = values[i++];
        } else {
            inversions += mid - i;
            tmp[k++] = values[j++];
        }
    }
    while (i < mid) {
        tmp[k++] = values[i++];
    }
    while (j < hi) {
        tmp[k++] = values[j++];
    }
    for (k = lo; k < hi; k++) {
        values[k] = tmp[k];
    }
    return inversions;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &values[i]);
    }
    printf("%lld\n", sort_count(0, n));
    return 0;
}

